0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n6:[\"$\",\"$L22\",null,{\"pageId\":4317,\"activeView\":{\"name\":\"default\",\"activeViewSuffix\":\"\",\"language\":\"en\"},\"children\":\"$@23\"}]\n9:null\ne:[[\"$\",\"title\",\"0\",{\"children\":\"Bhagavad-gītā As It Is 17.10\"}],[\"$\",\"meta\",\"1\",{\"name\":\"description\",\"content\":\"Srila Prabhupada''s books online\"}],[\"$\",\"meta\",\"2\",{\"name\":\"application-name\",\"content\":\"Vedabase\"}],[\"$\",\"link\",\"3\",{\"rel\":\"author\",\"href\":\"https://vedabase.io\"}],[\"$\",\"meta\",\"4\",{\"name\":\"author\",\"content\":\"A.C. Bhaktivedanta Swami - Srila Prabhupada\"}],[\"$\",\"meta\",\"5\",{\"name\":\"keywords\",\"content\":\"Srila Prabhupada,Krsna,Krishna,bhakti,devotion\"}],[\"$\",\"meta\",\"6\",{\"name\":\"creator\",\"content\":\"Prahlad Nrsimha das\"}]]\n"])self.__next_f.push([1,"25:T4b6,The purpose of food is to increase the duration of life, purify the mind and aid bodily strength. This is its only purpose. In the past, great authorities selected those foods that best aid health and increase life’s duration, such as milk products, sugar, rice, wheat, fruits and vegetables. These foods are very dear to those in the mode of goodness. Some other foods, such as baked corn and molasses, while not very palatable in themselves, can be made pleasant when mixed with milk or other foods. They are then in the mode of goodness. All these foods are pure by nature. They are quite distinct from untouchable things like meat and liquor. Fatty foods, as mentioned in the eighth verse, have no connection with animal fat obtained by slaughter. Animal fat is available in the form of milk, which is the most wonderful of all foods. Milk, butter, cheese and similar products give animal fat in a form which rules out any need for the killing of innocent creatures. It is only through brute mentality that this killing goes on. The civilized method of obtaining needed fat is by milk. Slaughter is the way of subhumans. Protein is amply available through split peas, dāl, whole wheat, etc.26:T4c6,Remnants of food may be eaten only when they are part of a meal that was first offered to the Supreme Lord or first eaten by saintly persons, especially the spiritual master. Otherwise the remnants of food are considered to be in the mode of darkness, and they increase infection or disease. Such foodstuffs, although very palatable to persons in the mode of darkness, are neither liked nor even touched by those in the mode of goodness. The best food is the remnants of what is offered to the Supreme Personality of Godhead. In Bhagavad-gītā the Supreme Lord says that He accepts preparations of vegetables, flour and milk when offered with devotion. Patraṁ puṣpaṁ phalaṁ toyam. Of course, devotion and love are the chief things which the Supreme Personality of Godhead accepts. But it is also mentioned that the prasādam should be prepared in a particular way. Any food prepared by the injunctions of the scripture and offered to the Supreme Personality of Godhead can be taken even if prepared long, long ago, because such food is transcendental. Therefore to make food antiseptic, eatable and palatable for all persons, one should offer food to the Supreme Personality of Godhead."])self.__next_f.push([1,"23:[\"$\",\"div\",null,{\"className\":\"flex flex-col min-h-screen text-vb-normal-text\",\"children\":[[\"$\",\"$L1a\",null,{\"className\":\"w-full left-0 z-30 bg-vb-body/95\",\"children\":[\"$\",\"$L1b\",null,{\"mainMenu\":\"$L24\",\"page\":{\"id\":4317,\"meta\":{\"type\":\"books.Verse\",\"slug\":\"10\",\"show_in_menus\":false,\"seo_title\":\"\",\"search_description\":\"\",\"first_published_at\":null,\"alias_of\":null,\"locale\":\"en\